const accounts = $input.all().map(item => item.json);
const request = $('01 Receber demanda GG Conta').first()?.json ?? {};
const targetGaps = Array.isArray(request.target_gaps) ? request.target_gaps : ['folha_pagamento', 'boleto_pix', 'crescimento_liquido_pj', 'gestao_vencidos'];

const evaluated = [];
const oppFolha = [];
const oppCobranca = [];
const oppVencidos = [];

for (const acc of accounts) {
  const employees = Number(acc.employees_count || 0);
  const rev = Number(acc.months_revenue_12m || 0);
  const score = Number(acc.credit_score || 0);
  const protests = Number(acc.protests_count || 0);
  const taxReg = acc.tax_regularity !== false;

  let eligibility = 'ELIGIBLE';
  const limitations = [];
  if (protests > 0) {
    eligibility = 'UNDETERMINED';
    limitations.push('RESTRICTION_RECURRENT: ' + protests + ' protesto(s) ativo(s).');
  }
  if (!taxReg) {
    limitations.push('RESTRICTION_NEW: Regularidade fiscal pendente.');
  }

  const opps = [];
  if (employees >= 10 && !acc.payroll_active && eligibility === 'ELIGIBLE') {
    const opp = {
      cnpj: acc.cnpj,
      razao_social: acc.razao_social,
      product: 'FOLHA_DE_PAGAMENTO',
      potential_gain: 4.0,
      reason_code: 'CROSS_SELL_FOLHA_PAGAMENTO',
      rationale: acc.razao_social + ' (' + employees + ' colaboradores) elegível para capturar 4,0 pts de Folha.'
    };
    opps.push(opp);
    oppFolha.push(opp);
  }

  if (rev >= 1000000 && (!acc.billing_active || !acc.pix_active) && eligibility === 'ELIGIBLE') {
    const opp = {
      cnpj: acc.cnpj,
      razao_social: acc.razao_social,
      product: 'COBRANCA_E_PIX_EMPRESARIAL',
      potential_gain: 4.0,
      reason_code: 'CROSS_SELL_COBRANCA_PIX',
      rationale: acc.razao_social + ' (R$ ' + (rev/1e6).toFixed(1) + 'M/ano) elegível para capturar 4,0 pts de Boleto/PIX.'
    };
    opps.push(opp);
    oppCobranca.push(opp);
  }

  if (score >= 600 && score < 750 && protests === 0) {
    const opp = {
      cnpj: acc.cnpj,
      razao_social: acc.razao_social,
      product: 'MONITORAMENTO_PREVENTIVO_MORA',
      potential_gain: 9.34,
      reason_code: 'MONITORAMENTO_PREVENTIVO_MORA',
      rationale: acc.razao_social + ' (Score ' + score + ') monitoramento para blindar 9,34 pts de Vencidos < 59d.'
    };
    opps.push(opp);
    oppVencidos.push(opp);
  }

  evaluated.push({
    account_ref: acc.cnpj,
    razao_social: acc.razao_social,
    eligibility_status: eligibility,
    evidence_refs: ['account_record_' + acc.cnpj, 'receita_federal_cnae'],
    opportunities: opps,
    limitations
  });
}

const output = {
  schema_version: '1.0.0',
  request_id: request.request_id || ('req-conta-' + Date.now()),
  provided_by: 'GERENTE_GERAL_CONTA',
  mediated_by: 'MOTOR_CONSOLIDACAO_360',
  operating_phase: 'ACCOUNT_LEVEL_FUTURE',
  account_data_status: 'AVAILABLE',
  portfolio_signals: [
    { signal: 'Carteira analisada com ' + accounts.length + ' empresas ativas.', evidence_status: 'CONFIRMED', use_in_plan: 'ALLOW' },
    { signal: 'Identificadas ' + (oppFolha.length + oppCobranca.length) + ' oportunidades aderentes aos gaps de Agosto/2026.', evidence_status: 'CONFIRMED', use_in_plan: 'ALLOW' }
  ],
  account_candidates: evaluated.filter(e => e.eligibility_status === 'ELIGIBLE' && e.opportunities.length > 0).map(e => ({
    account_ref: e.account_ref,
    eligibility_status: e.eligibility_status,
    evidence_refs: e.evidence_refs
  })),
  summary: {
    total_accounts: accounts.length,
    eligible_count: evaluated.filter(e => e.eligibility_status === 'ELIGIBLE').length,
    opp_folha_prioritaria: oppFolha.slice(0, 3),
    opp_cobranca_prioritaria: oppCobranca.slice(0, 3),
    opp_blindagem_vencidos: oppVencidos.slice(0, 3)
  },
  limitations: ['Dados cadastrais autorizados da agência 6895', 'Efeito externo exige autorização expressa de Rafael.'],
  decision_authority: 'RAFAEL'
};

return [{ json: output }];
